export function convoyResult(d,config,argusDestroyed=false){
 const total=Math.max(d.total,config.busCount*config.initialPassengers+config.civiliansPerPickup*config.map.pickups.length),unreached=Math.max(0,total-d.total),fraction=total?d.saved/total:0,thresholds=config.results?.rankThresholds||{S:.9,A:.75,B:.5,C:0};
 const rank=Object.entries(thresholds).sort((a,b)=>b[1]-a[1]).find(([,threshold])=>fraction>=threshold)?.[0]||'C';
 return Object.freeze({outcome:d.phase,saved:d.saved,killed:d.lost,leftBehind:d.unsaved+d.waiting+unreached,unreached,total,savedFraction:fraction,busesEscaped:d.buses.filter(b=>b.escaped).length,busesTotal:d.buses.length,completionSeconds:d.time,argusDestroyed:!!argusDestroyed,rank});
}
export function convoyTime(seconds){const s=Math.max(0,Math.round(seconds));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}
export class ConvoyResults {
 constructor(parent,{onOpen=()=>{},onClose=()=>{},onRestart=()=>{}}={}){
  Object.assign(this,{onOpen,onClose,onRestart});this.seen=null;this.dialog=document.createElement('dialog');this.dialog.id='convoy-results';this.dialog.setAttribute('aria-labelledby','convoy-result-title');this.dialog.innerHTML='<p class="convoy-result-eyebrow">CROSSFIRE / EVACUATION REPORT</p><div class="convoy-result-heading"><h2 id="convoy-result-title"></h2><div class="convoy-rank" data-rank aria-label="Mission rank"></div></div><p data-score></p><dl class="convoy-result-grid"><div><dt>CIVILIANS SAVED</dt><dd data-saved></dd></div><div><dt>KILLED</dt><dd data-killed></dd></div><div><dt>LEFT BEHIND</dt><dd data-left></dd></div><div><dt>BUSES ESCAPED</dt><dd data-buses></dd></div><div><dt>COMPLETION TIME</dt><dd data-time></dd></div><div><dt>ARGUS</dt><dd data-argus></dd></div></dl><p class="convoy-result-note" data-note></p><p class="convoy-result-note" data-grades></p><div class="convoy-result-actions"><button data-close>Keep observing</button><button data-restart>Rebuild & retry</button></div>';
  parent.append(this.dialog);this.dialog.querySelector('[data-close]').onclick=()=>this.dialog.close();this.dialog.querySelector('[data-restart]').onclick=()=>{this.dialog.close();this.onRestart();};this.dialog.addEventListener('close',()=>this.onClose());
 }
 update(mission){if(!mission.result){this.seen=null;if(this.dialog.open)this.dialog.close();return;}if(this.seen!==mission.result){this.seen=mission.result;this.show(mission);}}
 show(mission){const r=mission.result;if(!r)return;const set=(key,value)=>this.dialog.querySelector('[data-'+key+']').textContent=value;this.dialog.querySelector('h2').textContent=r.outcome==='success'?'Evacuation complete':'Convoy lost';set('rank',r.rank);set('score',Math.round(r.savedFraction*100)+'% of '+r.total+' civilians saved');set('saved',r.saved);set('killed',r.killed);set('left',r.leftBehind);set('buses',r.busesEscaped+' / '+r.busesTotal);set('time',convoyTime(r.completionSeconds));set('argus',r.argusDestroyed?'DESTROYED':'OPERATIONAL');set('note','Recorded at mission completion.'+(r.unreached?' Left behind includes '+r.unreached+' civilians at unreached pickups.':''));set('grades',Object.entries(mission.config.results?.rankThresholds||{S:.9,A:.75,B:.5,C:0}).map(([rank,min])=>rank+' '+Math.round(min*100)+'%+').join(' · '));if(!this.dialog.open){this.onOpen();this.dialog.showModal();}}
}
